package ru.kupiora.radar;
import android.view.*;import android.widget.*;import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;
/** Runs only in the separate audit APK. Restores preferences and removes synthetic notices. */
public class AuditInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle arguments){super.onCreate(arguments);start();}
 MainActivity ui;
 View find(View root,String text){if(root instanceof TextView&&text.equals(((TextView)root).getText().toString()))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View v=find(group.getChildAt(i),text);if(v!=null)return v;}}return null;}
 int checks;void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;}
 @Override public void onStart(){Context c=getTargetContext();android.content.SharedPreferences p=Store.prefs(c);Map<String,?> backup=new HashMap<>(p.getAll());Bundle result=new Bundle();try{Catalog.init(c);Store.all(c);List<JSONObject> original=Feed.parse(Store.feed(c));check(!original.isEmpty(),"fixture available");p.edit().putBoolean("onboarded",true).putLong("last_attempt",System.currentTimeMillis()).putInt("syncCatalogRevision",2).commit();ui=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
 for(int cycle=1;cycle<=3;cycle++){
 final Throwable[] uiError={null};runOnMainSync(()->{try{for(Catalog.Topic root:Catalog.roots){ui.show("topics");View title=find(ui.root,root.title+"  ›");check(title!=null&&title.performClick(),"root title clickable");check(ui.screen.equals("topic:"+root.id),"root opens description");check(ui.branchToggle!=null,"subscription control exists");ui.branchToggle.performClick();check(Store.count(Store.selected(c),root.id)==0,"whole direction off");ui.branchToggle.performClick();check(Store.count(Store.selected(c),root.id)==Catalog.leaves(root.id).size(),"whole direction on");ui.handleBack();check(ui.screen.equals("topics"),"system Back returns to topics");}for(Catalog.Topic topic:Catalog.index.values()){ui.show("topic:"+topic.id);check(ui.screen.equals("topic:"+topic.id),"all topic descriptions reachable");check(ui.branchToggle!=null,"all topic switches exist");}ui.show("home");}catch(Throwable error){uiError[0]=error;}});if(uiError[0]!=null)throw new AssertionError(uiError[0]);

 p.edit().putString(Inbox.KEY,"[]").putStringSet("digest_pending",new HashSet<>()).putString("digest_documents","{}").commit();
 JSONObject work=new JSONObject(original.get(0).toString()).put("id","audit-work-"+cycle).put("title","ПРОВЕРКА: работа").put("summary","Синтетическая запись только для проверки; удаляется после теста.").put("archive",false).put("categoryId","work").put("topicIds",new JSONArray().put(Catalog.leaves("work").get(0)));
 JSONObject housing=new JSONObject(work.toString()).put("id","audit-housing-"+cycle).put("title","ПРОВЕРКА: жильё").put("categoryId","housing").put("topicIds",new JSONArray().put(Catalog.leaves("housing").get(0)));
 Set<String> pending=new HashSet<>(Arrays.asList(work.getString("id"),housing.getString("id")));JSONObject queue=new JSONObject().put(work.getString("id"),work).put(housing.getString("id"),housing);
 p.edit().putStringSet("digest_pending",pending).putString("digest_documents",queue.toString()).putString("digest_interval","daily").putLong("digest_last",System.currentTimeMillis()-172800000L).commit();
 SyncJob.deliverDigest(c,Collections.emptyList());check(Inbox.count(c)==2,"delivery survives response omission");check(Inbox.unreadFor(c,"work")==1,"work badge");check(Inbox.unreadFor(c,"housing")==1,"housing badge");check(Inbox.unreadFor(c,"health")==0,"no unrelated badge");check(p.getStringSet("digest_pending",Collections.emptySet()).isEmpty(),"delivered queue cleared");
 check(!Inbox.addDocument(c,work),"duplicate suppressed");check(Inbox.load(c).getJSONObject(0).has("sourceUrl"),"source retained");
 NotificationManager nm=c.getSystemService(NotificationManager.class);if(nm.areNotificationsEnabled()){long postedBy=System.currentTimeMillis()+3000;while(nm.getActiveNotifications().length==0&&System.currentTimeMillis()<postedBy)Thread.sleep(50);check(nm.getActiveNotifications().length>0,"real system notification posted");check(nm.getActiveNotifications()[0].getNotification().getChannelId().equals(SyncJob.CHANNEL),"correct channel");}
 Inbox.markCategoryRead(c,"work");check(Inbox.unreadFor(c,"work")==0,"work clears after reading");check(Inbox.unreadFor(c,"housing")==1,"housing stays unread");Inbox.markCategoryRead(c,"");check(Inbox.count(c)==0,"all read");long clearedBy=System.currentTimeMillis()+2000;while(nm.getActiveNotifications().length>0&&System.currentTimeMillis()<clearedBy)Thread.sleep(50);check(nm.getActiveNotifications().length==0,"badge removed");
 p.edit().putStringSet("digest_pending",new HashSet<>(Arrays.asList("missing-document"))).putLong("digest_last",System.currentTimeMillis()-172800000L).commit();SyncJob.deliverDigest(c,Collections.emptyList());check(p.getStringSet("digest_pending",Collections.emptySet()).contains("missing-document"),"unknown pending not lost");
 Store.toggle(c,"work",false);p.edit().putStringSet("digest_pending",new HashSet<>(Arrays.asList(work.getString("id")))).putString("digest_documents",new JSONObject().put(work.getString("id"),work).toString()).putLong("digest_last",System.currentTimeMillis()-172800000L).commit();SyncJob.deliverDigest(c,Collections.emptyList());check(Inbox.count(c)==0,"disabled topic silent");check(p.getStringSet("digest_pending",Collections.emptySet()).isEmpty(),"disabled pending cleared");Store.all(c);
 }
 result.putString("stream","PASS: 3 cycles; "+checks+" checks; permission="+c.getSystemService(NotificationManager.class).areNotificationsEnabled()+"; queue retention, delivery, category indicators, source, read, dedup, disabled topics. Preferences restored.\n");
 }catch(Throwable error){result.putString("stream","FAIL: "+error.toString()+"\n");result.putString("error",error.toString());}finally{if(ui!=null)runOnMainSync(()->ui.finish());c.getSystemService(NotificationManager.class).cancel(101);android.content.SharedPreferences.Editor edit=p.edit().clear();for(Map.Entry<String,?> item:backup.entrySet()){String key=item.getKey();Object value=item.getValue();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);else if(value instanceof Set)edit.putStringSet(key,new HashSet<>((Set<String>)value));}edit.commit();SyncJob.updateSystemBadge(c);}finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
